#include "eidos_wasm.h"

static int32_t on_exp(EidosEvent *event)
{
    EidosMonExp *e = (EidosMonExp *)event;
    if (eidos_setting_get("slow_exp") == 1) {
        e->amount /= 2;
    }
    return EIDOS_EVENT_CONTINUE;
}

