#include "eidos_wasm.h"

static uint32_t g_faints;

static int32_t on_faint(EidosEvent *event)
{
    EidosBattleFaint *e = (EidosBattleFaint *)event;
    char line[24] = "Faints: ";
    char digits[11];
    uint32_t n = 0, v, i;
    if (e->side != 0) {
        return EIDOS_EVENT_CONTINUE;
    }
    g_faints++;
    v = g_faints;
    do {
        digits[n++] = (char)('0' + v % 10);
        v /= 10;
    } while (v);
    for (i = 0; i < n; i++) {
        line[8 + i] = digits[n - 1 - i];
    }
    line[8 + n] = 0;
    eidos_panel_set(0, line);
    return EIDOS_EVENT_CONTINUE;
}

EIDOS_EXPORT("eidos_mod_start")
int32_t eidos_mod_start(void)
{
    return eidos_on(EIDOS_EVENT_BATTLE_FAINT, (uint32_t)(uintptr_t)on_faint);
}

