{
    EidosMonExp *e = (EidosMonExp *)event;
    int32_t cap = 100;
    eidos_table_get("caps", (int32_t)eidos_badge_count(), &cap);
    if ((int32_t)e->level >= cap) {
        e->amount = 0;
    }
    return EIDOS_EVENT_CONTINUE;
