static int32_t on_catch(EidosEvent *event)
{
    EidosCatchResult *e = (EidosCatchResult *)event;
    uint32_t who = eidos_event_player();
    char line[40] = "Player 0 caught a Pokemon.";
    if (who != 0 && e->caught) {
        line[7] = (char)('0' + who % 10);
        eidos_message(line);
    }
    return EIDOS_EVENT_CONTINUE;
}

EIDOS_EXPORT("eidos_mod_start")
int32_t eidos_mod_start(void)
{
    return eidos_on(EIDOS_EVENT_CATCH_RESULT, (uint32_t)(uintptr_t)on_catch);
}

